import numpy as np
from scipy.stats import qmc

s = np.array([[0.8050029237453802, 0.8079407897364937, 0.515325561042142], [0.2858013800881416, 0.053930702381656426, 0.38336888078551823], [0.40847320541999865, 0.045275193902445166, 0.04875771072716806], [0.9991761150650714, 0.6523691115879877, 0.23451020166982395], [0.43494755222514203, 0.9741861932592554, 0.8976776081085488], [0.844231037608741, 0.39240466433477816, 0.4930230187317426], [0.676689351831066, 0.06080271295805606, 0.5555961169207234], [0.27145160453010153, 0.8796511733349222, 0.06421443731219101], [0.679181533021365, 0.8700885023275033, 0.2273185251609081], [0.895448239414126, 0.872195468024335, 0.01851721767021075], [0.7074955673371773, 0.0011996835868286482, 0.5033639655536645], [0.4366670521756527, 0.2032528361145648, 0.32494264457560607]])

@test
def test_geometric_discrepancy():
    assert abs(qmc.geometric_discrepancy(s) - 0.0850278875456031) < 1e-12
    assert abs(qmc.geometric_discrepancy(s, method='mst') - 0.3367594617157605) < 1e-12
    assert abs(qmc.geometric_discrepancy(s, metric='cityblock') - 0.14264139624439764) < 1e-12

class E(qmc.QMCEngine):
    def _random(self, n: int):
        return np.full((n, self.d), 0.25)

@test
def test_engine():
    e = E(2)
    r = e.random(3)
    assert r.shape == (3, 2) and e.num_generated == 3
    e.fast_forward(2)
    assert e.num_generated == 5
